package tn.esprit.raghd_selmi_4act.service.impl;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import tn.esprit.raghd_selmi_4act.entities.Vehicule;
import tn.esprit.raghd_selmi_4act.repository.VehiculeRepository;
import tn.esprit.raghd_selmi_4act.service.interfaces.IVehiculeService;

import java.util.List;

@Service
@RequiredArgsConstructor
public class VehiculeServiceImpl implements IVehiculeService {

    // Injected by Spring (constructor injection, generated by Lombok)
    private final VehiculeRepository repository;

    @Override
    public Vehicule addVehicule(Vehicule entity) {
        return repository.save(entity);
    }

    @Override
    public Vehicule updateVehicule(Vehicule entity) {
        return repository.save(entity);
    }

    @Override
    public List<Vehicule> retrieveAllVehicules() {
        return repository.findAll();
    }

    @Override
    public Vehicule retrieveVehicule(Long id) {
        return repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Vehicule not found with id " + id));
    }

    @Override
    public void removeVehicule(Long id) {
        repository.deleteById(id);
    }
}
